import { Sparkles, Wand2 } from 'lucide-react'
import React from 'react'

export interface SourceBadgeProps {
  source: 'gemini' | 'template'
  model?: string
  className?: string
}

/**
 * Honest SourceBadge component communicating whether content was generated by Gemini
 * or derived deterministically from local smart templates.
 *
 * @param props - SourceBadge properties.
 * @returns Styled attribution badge.
 */
export function SourceBadge({
  source,
  model,
  className = '',
}: SourceBadgeProps): React.ReactElement {
  if (source === 'gemini') {
    return (
      <span
        title={model ? `Generated with ${model}` : 'Generated with Gemini'}
        className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold bg-purple-100 text-purple-900 dark:bg-purple-950/70 dark:text-purple-300 border border-purple-200 dark:border-purple-800 select-none ${className}`.trim()}
      >
        <Sparkles
          className="w-3.5 h-3.5 text-purple-600 dark:text-purple-400"
          aria-hidden="true"
        />
        <span>Gemini</span>
      </span>
    )
  }

  return (
    <span
      title="Generated deterministically using Festora celebration templates"
      className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium bg-[var(--bg-surface-elevated)] text-[var(--text-secondary)] border border-[var(--border-subtle)] select-none ${className}`.trim()}
    >
      <Wand2
        className="w-3.5 h-3.5 text-[var(--text-muted)]"
        aria-hidden="true"
      />
      <span>Smart template</span>
    </span>
  )
}
